const entrada = $input.first()?.json || {};

function texto(valor) {
  return String(valor ?? '').trim();
}

function limparJsonTexto(valor) {
  let textoLimpo = texto(valor);

  textoLimpo = textoLimpo
    .replace(/```json/gi, '')
    .replace(/```javascript/gi, '')
    .replace(/```js/gi, '')
    .replace(/```/g, '')
    .trim();

  return textoLimpo;
}

function tentarParse(valor) {
  if (valor === null || valor === undefined) {
    return null;
  }

  if (typeof valor === 'object') {
    return valor;
  }

  if (typeof valor !== 'string') {
    return null;
  }

  let conteudo = limparJsonTexto(valor);

  try {
    return JSON.parse(conteudo);
  } catch {}

  const inicioObjeto = conteudo.indexOf('{');
  const fimObjeto = conteudo.lastIndexOf('}');

  if (
    inicioObjeto !== -1 &&
    fimObjeto !== -1 &&
    fimObjeto > inicioObjeto
  ) {
    conteudo = conteudo.slice(
      inicioObjeto,
      fimObjeto + 1
    );

    try {
      return JSON.parse(conteudo);
    } catch {}
  }

  const inicioArray = conteudo.indexOf('[');
  const fimArray = conteudo.lastIndexOf(']');

  if (
    inicioArray !== -1 &&
    fimArray !== -1 &&
    fimArray > inicioArray
  ) {
    conteudo = conteudo.slice(
      inicioArray,
      fimArray + 1
    );

    try {
      return JSON.parse(conteudo);
    } catch {}
  }

  return null;
}

function localizarEstrutura(valor, profundidade = 0) {
  if (
    valor === null ||
    valor === undefined ||
    profundidade > 10
  ) {
    return null;
  }

  const convertido = tentarParse(valor);

  if (convertido !== valor && convertido !== null) {
    return localizarEstrutura(
      convertido,
      profundidade + 1
    );
  }

  if (Array.isArray(valor)) {
    for (const item of valor) {
      const encontrado = localizarEstrutura(
        item,
        profundidade + 1
      );

      if (encontrado) {
        return encontrado;
      }
    }

    return null;
  }

  if (typeof valor !== 'object') {
    return null;
  }

  // Estrutura final esperada
  if (
    valor.orcamento &&
    Array.isArray(valor.itens)
  ) {
    return valor;
  }

  // Algumas APIs retornam o conteúdo dentro de output
  if (
    valor.output?.orcamento &&
    Array.isArray(valor.output?.itens)
  ) {
    return valor.output;
  }

  // Algumas APIs retornam dentro de data
  if (
    valor.data?.orcamento &&
    Array.isArray(valor.data?.itens)
  ) {
    return valor.data;
  }

  // Resposta do OpenAI Responses API
  if (Array.isArray(valor.output)) {
    for (const output of valor.output) {
      if (!Array.isArray(output?.content)) {
        continue;
      }

      for (const content of output.content) {
        const candidato =
          content?.text ??
          content?.output_text ??
          content?.json ??
          content;

        const encontrado = localizarEstrutura(
          candidato,
          profundidade + 1
        );

        if (encontrado) {
          return encontrado;
        }
      }
    }
  }

  // Estruturas comuns de outras APIs
  const camposProvaveis = [
    'text',
    'content',
    'output_text',
    'response',
    'result',
    'message',
    'choices',
    'body',
    'data'
  ];

  for (const campo of camposProvaveis) {
    if (valor[campo] === undefined) {
      continue;
    }

    const encontrado = localizarEstrutura(
      valor[campo],
      profundidade + 1
    );

    if (encontrado) {
      return encontrado;
    }
  }

  // Busca recursiva final
  for (const propriedade of Object.keys(valor)) {
    const encontrado = localizarEstrutura(
      valor[propriedade],
      profundidade + 1
    );

    if (encontrado) {
      return encontrado;
    }
  }

  return null;
}

const parsed = localizarEstrutura(entrada);

